33.     {
34.         // Greek ordinals have complex gender agreement; return base form for simplicity
35.         return ConvertImpl(number, false);
36.     }
37. 
38.     private string ConvertImpl(long number, bool returnPluralized)
39.     {
40.         if (number < 0)
41.         {
42.             return $"μείον {ConvertImpl(-number, false)}";
43.         }
44. 
45.         if (number < 10)
46.         {
47.             return returnPluralized ? UnitsMapPluralized[number] : UnitsMap[number];
48.         }
49. 
50.         if (number < 20)
51.         {
52.             return TeenMap[number - 10];
53.         }
54. 
55.         if (number < 100)
56.         {
57.             return ConvertTens(number, returnPluralized);
58.         }
59. 
60.         if (number < 1000)
61.         {
62.             return ConvertHundreds(number, returnPluralized);
63.         }
64. 
65.         if (number < 1_000_000)
66.         {
67.             return ConvertThousands(number);
68.         }
69. 
70.         if (number < 1_000_000_000)
71.         {
72.             return ConvertMillions(number);
73.         }
74. 
75.         return ConvertBillions(number);
76.     }
