{"path":"C:\Users\aajohn\AppData\Local\Temp\sv-d55e974bb1804789be222d6a2b5a6ca2\symbolize2.py","file_text":"import bisect
from elftools.elf.elffile import ELFFile
from elftools.elf.sections import SymbolTableSection
from elftools.dwarf.descriptions import describe_form_class

DEBUG = r"C:\Users\aajohn\AppData\Local\Temp\sv-d55e974bb1804789be222d6a2b5a6ca2\sym\_.debug__.debug"

FRAMES = [
    ("#01", 0x222098),
    ("#02", 0x2241ac),
    ("#03", 0x1abc80),
    ("#04", 0x1abd14),
    ("#05", 0x16dfa4),
    ("#06", 0x16db6c),
    ("#07", 0x16de04),
]

def collect_symbols(elf):
    syms = []
    for sec in elf.iter_sections():
        if not isinstance(sec, SymbolTableSection):
            continue
        for sym in sec.iter_symbols():
            if sym['st_info']['type'] != 'STT_FUNC':
                continue
            val, size = sym['st_value'], sym['st_size']
            if val == 0 or not sym.name:
                continue
            syms.append((val, size, sym.name))
    syms.sort()
    return syms

def sym_lookup(syms, addr, addrs):
    idx = bisect.bisect_right(addrs, addr) - 1
    if idx < 0:
        return None
    val, size, name = syms[idx]
    return name, addr - val, size

def die_name(die):
    n = die.attributes.get('DW_AT_name')
    if n:
        return n.value.decode('utf-8', 'replace')
    spec = die.attributes.get('DW_AT_specification') or die.attributes.get('DW_AT_abstract_origin')
    if spec:
        try:
            ref = die.cu.get_DIE_from_refaddr(spec.value + die.cu.cu_offset) if spec.form.startswith('DW_FORM_ref') else None
        except Exception:
            ref = None
        if ref is not None:
            return die_name(ref)
    return None

def die_ranges(die, dwarf):
    low = die.attributes.get('DW_AT_low_pc')
    high = die.attributes.get('DW_AT_high_pc')
    if low is not None and high is not None:
        low_v = low.value
        hc = describe_form_class(high.form)
        high_v = high.value if hc == 'address' else low_v + high.value
        return [(low_v, high_v)]
    rng = die.attributes.get('DW_AT_ranges')
    if rng is not None and dwarf.has_CU_range_lists():
        try:
            rlists = dwarf.range_lists()
            entries = rlists.get_range_list_at_offset(rng.value)
            base = 0
            cu_die = die.cu.get_top_DIE()
            lp = cu_die.attributes.get('DW_AT_low_pc')
            if lp is not None:
                base = lp.value
            out = []
            for e in entries:
                if hasattr(e, 'base_address') and e.__class__.__name__ == 'BaseAddressEntry':
                    base = e.base_address
                else:
                    out.append((base + e.begin_offset, base + e.end_offset))
            return out
        except Exception:
            return []
    return []

def dwarf_frame_info(dwarf, addr):
    """Return list of (name, inlined?) innermost-first for addr."""
    for cu in dwarf.iter_CUs():
        top = cu.get_top_DIE()
        for sub in top.iter_children():
            if sub.tag != 'DW_TAG_subprogram':
                continue
            rs = die_ranges(sub, dwarf)
            if not any(lo <= addr < hi for lo, hi in rs):
                continue
            name = die_name(sub)
            chain = [(name, False)]
            _walk_inlines(sub, addr, dwarf, chain)
            chain.reverse()
            return chain
    return None

def _walk_inlines(die, addr, dwarf, chain):
    for child in die.iter_children():
        if child.tag == 'DW_TAG_inlined_subroutine':
            rs = die_ranges(child, dwarf)
            if any(lo <= addr < hi for lo, hi in rs):
                chain.append((die_name(child) or '?', True))
                _walk_inlines(child, addr, dwarf, chain)
        elif child.tag in ('DW_TAG_lexical_block',):
            _walk_inlines(child, addr, dwarf, chain)

def build_line_lookup(dwarf):
    rows = []  # (addr, file, line)
    for cu in dwarf.iter_CUs():
        lp = dwarf.line_program_for_CU(cu)
        if lp is None:
            continue
        fe = lp['file_entry']
        seq = []
        for e in lp.get_entries():
            if e.state is None:
                continue
            st = e.state
            seq.append((st.address, st.file, st.line, st.end_sequence))
        for i in range(len(seq) - 1):
            a, fidx, line, end = seq[i]
            na = seq[i+1][0]
            if end:
                continue
            fname = fe[fidx - 1].name.decode() if 0 < fidx <= len(fe) else '?'
            rows.append((a, na, fname, line))
    rows.sort()
    return rows

def line_lookup(rows, addr):
    los = [r[0] for r in rows]
    idx = bisect.bisect_right(los, addr) - 1
    if idx < 0:
        return None
    a, na, fname, line = rows[idx]
    if a <= addr < na:
        return fname, line
    return None

def main():
    with open(DEBUG, 'rb') as f:
        elf = ELFFile(f)
        syms = collect_symbols(elf)
        addrs = [s[0] for s in syms]
        dwarf = elf.get_dwarf_info()
        rows = build_line_lookup(dwarf)
        print("=== Symbolicated .NET runtime frames (libmonosgen-2.0.so) ===\n")
        for tag, addr in FRAMES:
            s = sym_lookup(syms, addr, addrs)
            symtxt = f"{s[0]} + 0x{s[1]:x}" if s else "?"
            ln = line_lookup(rows, addr)
            lntxt = f"{ln[0]}:{ln[1]}" if ln else "?"
            frames = dwarf_frame_info(dwarf, addr)
            print(f"{tag}  pc 0x{addr:08x}")
            print(f"      symbol : {symtxt}")
            print(f"      source : {lntxt}")
            if frames:
                for i, (nm, inl) in enumerate(frames):
                    kind = "inlined into" if (inl or i < len(frames)-1) else "function"
                    tagi = "  (inlined)" if inl else ""
                    print(f"      dwarf  : {nm}{tagi}")
            print()

if __name__ == '__main__':
    main()
"}

