181.         private void UpdateInstructorCourses(string[] selectedCourses, Instructor instructorToUpdate)
182.         {
183.             if (selectedCourses == null)
184.             {
185.                 instructorToUpdate.CourseAssignments = new List<CourseAssignment>();
186.                 return;
187.             }
188. 
189.             var selectedCoursesHS = new HashSet<string>(selectedCourses);
190.             var instructorCourses = new HashSet<int>
191.                 (instructorToUpdate.CourseAssignments.Select(c => c.Course.CourseID));
192.             foreach (var course in db.Courses)
193.             {
194.                 if (selectedCoursesHS.Contains(course.CourseID.ToString()))
195.                 {
196.                     if (!instructorCourses.Contains(course.CourseID))
197.                     {
198.                         instructorToUpdate.CourseAssignments.Add(new CourseAssignment { InstructorID = instructorToUpdate.ID, CourseID = course.CourseID });
199.                     }
200.                 }
201.                 else
202.                 {
203. 
204.                     if (instructorCourses.Contains(course.CourseID))
205.                     {
206.                         CourseAssignment courseToRemove = instructorToUpdate.CourseAssignments.SingleOrDefault(i => i.CourseID == course.CourseID);
207.                         db.Entry(courseToRemove).State = EntityState.Deleted;
208.                     }
209.                 }
210.             }
211.         }
