            context.Departments.Add(department);
            context.SaveChanges();
            var course = new Course { CourseID = courseId, Title = "Chemistry", Credits = 3, DepartmentID = department.DepartmentID };
            context.Courses.Add(course);
            context.SaveChanges();
            return course;
        }

        [Fact]
        public void Index_NoFilters_ReturnsViewWithInstructors()
        {
            using var context = TestSupport.CreateContext();
            SeedInstructor(context, "Zheng");
            SeedInstructor(context, "Abercrombie");
            var controller = CreateController(context);

            var result = Assert.IsType<ViewResult>(controller.Index(null, null));
            var model = Assert.IsType<InstructorIndexData>(result.Model);

            Assert.Equal(new[] { "Abercrombie", "Zheng" }, model.Instructors.Select(i => i.LastName));
        }

