        {
            using var context = TestSupport.CreateContext();
            var instructor = SeedInstructor(context);
            var course = SeedCourse(context);
            context.CourseAssignments.Add(new CourseAssignment { InstructorID = instructor.ID, CourseID = course.CourseID });
            context.SaveChanges();
            var controller = CreateController(context);

            var result = Assert.IsType<ViewResult>(controller.Index(instructor.ID, null));
            var model = Assert.IsType<InstructorIndexData>(result.Model);

            Assert.Equal(instructor.ID, controller.ViewBag.InstructorID);
            Assert.Contains(model.Courses, c => c.CourseID == course.CourseID);
        }

