            context.OfficeAssignments.Add(new OfficeAssignment { InstructorID = instructor.ID, Location = "Room 1" });
            var department = new Department { Name = "English", Budget = 1000, StartDate = new DateTime(2007, 9, 1), InstructorID = instructor.ID };
            context.Departments.Add(department);
