        [Fact]
        public void ReproduceSave()
        {
            var dbName = Guid.NewGuid().ToString();
            using var context = TestSupport.CreateContext(dbName);
            var instructor = new Instructor { LastName = "Abercrombie", FirstMidName = "Kim", HireDate = new DateTime(1995, 3, 11) };
            context.Instructors.Add(instructor);
            context.SaveChanges();

            var toUpdate = context.Instructors
                .Include(i => i.OfficeAssignment)
                .Include(i => i.CourseAssignments)
                    .ThenInclude(c => c.Course)
                .Single(i => i.ID == instructor.ID);

            // Simulate binder creating an empty OfficeAssignment then controller nulling it
            toUpdate.OfficeAssignment = new OfficeAssignment();
            if (string.IsNullOrWhiteSpace(toUpdate.OfficeAssignment?.Location))
            {
                toUpdate.OfficeAssignment = null;
            }
            toUpdate.CourseAssignments = new List<CourseAssignment>();

            var sb = new StringBuilder();
            try
            {
                context.SaveChanges();
                sb.AppendLine("SAVE OK");
            }
            catch (Exception ex)
            {
                sb.AppendLine("EX=" + ex.GetType().FullName + " : " + ex.Message);
                if (ex.InnerException != null) sb.AppendLine("INNER=" + ex.InnerException.Message);
            }
            Assert.Fail(sb.ToString());
        }
    }
}
