3. /**
4.  * Async seam for refreshing prices from a backend before checkout. Tests
5.  * typically substitute a mock returning a resolved promise (e.g.
6.  * `vi.fn().mockResolvedValue({ ... })`).
7.  */
8. export interface PriceFetcher {
9.   fetchPriceCents(productId: string): Promise<number>;
10. }
11. 
12. /**
13.  * In-stock check seam used by Cart.checkout(). Implementations may resolve
14.  * with `available: true` and an optional `availableQuantity`, or reject /
15.  * resolve `available: false` to signal an inventory failure.
16.  */
17. export interface InventoryChecker {
18.   check(productId: string, quantity: number): Promise<InventoryDecision>;
19. }
20. 
21. export interface InventoryDecision {
22.   available: boolean;
23.   /** When provided and less than the requested quantity, callers should treat as a partial-stock denial. */
24.   availableQuantity?: number;
25.   /** Human-readable reason for an unavailable decision. */
26.   reason?: string;
27. }
28. 
29. export class InventoryError extends Error {
30.   constructor(
31.     message: string,
32.     readonly productId: string,
33.     readonly requested: number,
34.     readonly available: number | undefined,
35.   ) {
36.     super(message);
37.     this.name = "InventoryError";
38.   }
39. }
40. 
41. /**
42.  * Apply a fresh set of prices to a snapshot of cart lines. Returns a new
43.  * array with the same products but updated `unitPriceCents`. Throws if
44.  * any fetched price is not a non-negative integer.
45.  */
46. export async function refreshPrices(
47.   lines: readonly CartLine[],
48.   fetcher: PriceFetcher,
49. ): Promise<CartLine[]> {
50.   const refreshed: CartLine[] = [];
51.   for (const line of lines) {
52.     const price = await fetcher.fetchPriceCents(line.product.id);
53.     if (!Number.isInteger(price) || price < 0) {
54.       throw new RangeError(
55.         `fetcher returned invalid price ${price} for product ${line.product.id}`,
56.       );
57.     }
58.     const product: Product = { ...line.product, unitPriceCents: price };
59.     refreshed.push({ product, quantity: line.quantity });
60.   }
61.   return refreshed;
62. }
