    "constructor rejects out-of-range percent %s",
    (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
    },
  );

  it.each([0, 50, 100])("constructor accepts boundary percent %s", (percent) => {
    expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
  });

  it.each([
