    expect(new PercentageDiscountPolicy(percent).computeDiscountCents(subtotal)).toBe(
      expected,
    );
  });

  it.each([0, -500])("returns 0 for non-positive subtotal %i", (subtotal) => {
    expect(new PercentageDiscountPolicy(25).computeDiscountCents(subtotal)).toBe(0);
  });

