import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
  type WeightBracket,
} from "../src/shipping.ts";
import type { CartLine, Product } from "../src/product.ts";

function line(weightGrams: number | undefined, quantity = 1, id = "p"): CartLine {
  const product: Product = { id, name: "x", unitPriceCents: 100, weightGrams };
  return { product, quantity };
}

describe("FreeShippingCalculator", () => {
  it("always returns 0", () => {
    const calc = new FreeShippingCalculator();
    expect(calc.computeShippingCents([line(1000)], 5000)).toBe(0);
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  it.each([-1, 1.5])("constructor rejects invalid flatCents %s", (flat) => {
    expect(() => new FlatShippingCalculator(flat)).toThrow(RangeError);
  });

  it.each([-1, 2.5])("constructor rejects invalid freeOverCents %s", (freeOver) => {
    expect(() => new FlatShippingCalculator(500, freeOver)).toThrow(RangeError);
  });

  it("returns 0 for an empty cart regardless of the flat fee", () => {
    expect(new FlatShippingCalculator(500).computeShippingCents([], 0)).toBe(0);
  });

  it("charges the flat fee when there is no free-over threshold", () => {
    expect(new FlatShippingCalculator(599).computeShippingCents([line(100)], 100_000)).toBe(
      599,
    );
  });

  it("charges the flat fee when the subtotal is just below the threshold", () => {
    const calc = new FlatShippingCalculator(500, 5000);
    expect(calc.computeShippingCents([line(100)], 4999)).toBe(500);
  });

  it("ships free when the subtotal meets the free-over threshold (inclusive)", () => {
    const calc = new FlatShippingCalculator(500, 5000);
    expect(calc.computeShippingCents([line(100)], 5000)).toBe(0);
    expect(calc.computeShippingCents([line(100)], 6000)).toBe(0);
  });
});

describe("WeightBasedShippingCalculator", () => {
  const brackets: WeightBracket[] = [
    { upToGrams: 500, costCents: 300 },
    { upToGrams: 1000, costCents: 500 },
  ];

  it("constructor rejects an empty bracket list", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow(
      "at least one weight bracket is required",
    );
  });

  it.each([
    { upToGrams: 0, costCents: 100 },
    { upToGrams: 1.5, costCents: 100 },
    { upToGrams: 500, costCents: -1 },
    { upToGrams: 500, costCents: 2.5 },
  ])("constructor rejects invalid bracket %o", (bracket) => {
    expect(() => new WeightBasedShippingCalculator([bracket])).toThrow(RangeError);
  });

  it.each([-1, 2.5])("constructor rejects invalid overflowCostCents %s", (overflow) => {
    expect(() => new WeightBasedShippingCalculator(brackets, overflow)).toThrow(
      RangeError,
    );
  });

  it("returns 0 for an empty cart", () => {
    expect(new WeightBasedShippingCalculator(brackets).computeShippingCents([], 0)).toBe(0);
  });

  it("returns 0 when the total weight is 0 grams", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    expect(calc.computeShippingCents([line(undefined, 3)], 0)).toBe(0);
  });

  it("selects the first bracket whose upper bound covers the weight (boundary inclusive)", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    // exactly 500g falls in the first bracket
    expect(calc.computeShippingCents([line(500)], 0)).toBe(300);
    // 501g spills into the second bracket
    expect(calc.computeShippingCents([line(501)], 0)).toBe(500);
    // exactly 1000g still fits the second bracket
    expect(calc.computeShippingCents([line(1000)], 0)).toBe(500);
  });

  it("sorts unordered brackets before selecting", () => {
    const unordered: WeightBracket[] = [
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 500, costCents: 300 },
    ];
    const calc = new WeightBasedShippingCalculator(unordered);
    expect(calc.computeShippingCents([line(400)], 0)).toBe(300);
  });

  it("uses the explicit overflow cost when the weight exceeds every bracket", () => {
    const calc = new WeightBasedShippingCalculator(brackets, 900);
    expect(calc.computeShippingCents([line(1001)], 0)).toBe(900);
  });

  it("falls back to the heaviest bracket cost when no overflow cost is given", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    // 2000g > 1000g heaviest bracket => heaviest cost 500
    expect(calc.computeShippingCents([line(1000, 2)], 0)).toBe(500);
  });
});
