      { product: { id: "b", name: "b", unitPriceCents: 250, weightGrams: 100 }, quantity: 5 },
    ]);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("b");
  });

  it("does not mutate the original lines", async () => {
    const original = line("a", 100, 3);
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };

    await refreshPrices([original], fetcher);

    expect(original.product.unitPriceCents).toBe(100);
  });

  it.each([-1, 1.5, NaN])(
    "throws when the fetched price %s is not a non-negative integer",
    async (price) => {
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(price),
      };
      await expect(refreshPrices([line("a", 100)], fetcher)).rejects.toThrow(RangeError);
