  it("returns an empty array for empty input without calling the fetcher", async () => {
    const fetcher: PriceFetcher = { fetchPriceCents: vi.fn() };
    await expect(refreshPrices([], fetcher)).resolves.toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });
});

