{"file_text":"import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type {
  DiscountPolicy,
} from "../src/pricing.ts";
import type { TaxCalculator, AsyncTaxRateProvider } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import { InventoryError, type InventoryChecker, type PriceFetcher } from "../src/inventory.ts";
import type { Product } from "../src/product.ts";

function product(overrides: Partial<Product> = {}): Product {
  return { id: "p1", name: "Widget", unitPriceCents: 1000, weightGrams: 100, ...overrides };
}

describe("Cart line management", () => {
  it("merges quantity when adding the same product id twice", () => {
    const cart = new Cart();
    cart.add(product(), 2);
    cart.add(product(), 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.snapshot()).toHaveLength(1);
  });

  it("keeps distinct products as separate lines", () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 1);
    cart.add(product({ id: "b" }), 4);
    expect(cart.itemCount).toBe(5);
    expect(cart.snapshot()).toHaveLength(2);
  });

  it.each([0, -1, 1.5])("add rejects non-positive/non-integer quantity %s", (qty) => {
    expect(() => new Cart().add(product(), qty)).toThrow(RangeError);
  });

  it("add rejects a negative unit price", () => {
    expect(() => new Cart().add(product({ unitPriceCents: -1 }), 1)).toThrow(RangeError);
  });

  it("remove returns true for a known id and false for an unknown id", () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.remove("a")).toBe(false);
    expect(cart.remove("missing")).toBe(false);
  });

  it("updateQuantity replaces the quantity of an existing line", () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 2);
    cart.updateQuantity("a", 7);
    expect(cart.itemCount).toBe(7);
  });

  it("updateQuantity to 0 removes the line", () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 2);
    cart.updateQuantity("a", 0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it.each([-1, 1.5])("updateQuantity rejects invalid quantity %s", (qty) => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 2);
    expect(() => cart.updateQuantity("a", qty)).toThrow(RangeError);
  });

  it("updateQuantity throws for an unknown product", () => {
    expect(() => new Cart().updateQuantity("missing", 1)).toThrow(
      "Product missing is not in the cart",
    );
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 2);
    cart.add(product({ id: "b" }), 2);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("snapshot returns deep copies that cannot mutate cart state", () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 2);
    const snap = cart.snapshot();
    (snap[0] as { quantity: number }).quantity = 99;
    (snap[0].product as { unitPriceCents: number }).unitPriceCents = 1;
    // original cart is unaffected
    expect(cart.itemCount).toBe(2);
    expect(cart.snapshot()[0].product.unitPriceCents).toBe(1000);
  });
});

describe("Cart.totals pricing pipeline", () => {
  it("composes subtotal → discount → tax(on discounted) → shipping(on discounted)", () => {
    const discountPolicy: DiscountPolicy = { computeDiscountCents: vi.fn().mockReturnValue(500) };
    const taxCalculator: TaxCalculator = { computeTaxCents: vi.fn().mockReturnValue(150) };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator, region: "US-CA" });
    cart.add(product({ unitPriceCents: 1000 }), 2); // subtotal 2000

    const totals = cart.totals();

    expect(totals.subtotalCents).toBe(2000);
    expect(totals.discountCents).toBe(500);
    // tax computed on the discounted subtotal (1500), with the configured region
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1500, "US-CA");
    // shipping computed against the discounted subtotal
    expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      1500,
    );
    expect(totals.taxCents).toBe(150);
    expect(totals.shippingCents).toBe(300);
    expect(totals.totalCents).toBe(1500 + 150 + 300);
  });

  it("clamps a negative discount up to 0", () => {
    const discountPolicy: DiscountPolicy = { computeDiscountCents: () => -999 };
    const cart = new Cart({ discountPolicy });
    cart.add(product({ unitPriceCents: 1000 }), 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("clamps an over-subtotal discount down to the subtotal", () => {
    const discountPolicy: DiscountPolicy = { computeDiscountCents: () => 999_999 };
    const cart = new Cart({ discountPolicy });
    cart.add(product({ unitPriceCents: 1000 }), 2); // subtotal 2000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(2000);
    // fully discounted => tax base and total shrink accordingly
    expect(totals.totalCents).toBe(0);
  });

  it("clamps negative tax and shipping results to 0", () => {
    const cart = new Cart({
      taxCalculator: { computeTaxCents: () => -50 },
      shippingCalculator: { computeShippingCents: () => -20 },
    });
    cart.add(product({ unitPriceCents: 1000 }), 1);
    const totals = cart.totals();
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(1000);
  });

  it("uses default collaborators (no discount, no tax, free shipping) and region US", () => {
    const cart = new Cart();
    cart.add(product({ unitPriceCents: 1000 }), 3);
    expect(cart.totals()).toEqual({
      subtotalCents: 3000,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 3000,
    });
  });
});

describe("Cart.checkout", () => {
  it("refreshes prices through the priceFetcher before computing totals", async () => {
    const cart = new Cart();
    cart.add(product({ id: "a", unitPriceCents: 1000 }), 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };

    const result = await cart.checkout({ priceFetcher });

    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    expect(result.lines[0].product.unitPriceCents).toBe(1500);
    expect(result.totals.subtotalCents).toBe(3000);
  });

  it("validates inventory and throws InventoryError on an unavailable decision", async () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 4);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, reason: "discontinued" }),
    };

    const error = await cart.checkout({ inventoryChecker }).catch((e) => e);
    expect(error).toBeInstanceOf(InventoryError);
    expect(error.message).toBe("discontinued");
    expect(error.productId).toBe("a");
    expect(error.requested).toBe(4);
  });

  it("throws InventoryError on partial stock (availableQuantity < requested)", async () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 2 }),
    };

    const error = await cart.checkout({ inventoryChecker }).catch((e) => e);
    expect(error).toBeInstanceOf(InventoryError);
    expect(error.requested).toBe(5);
    expect(error.available).toBe(2);
    // default message is generated from the line details
    expect(error.message).toContain("insufficient stock for a");
  });

  it("passes inventory when availableQuantity meets the requested quantity", async () => {
    const cart = new Cart();
    cart.add(product({ id: "a", unitPriceCents: 1000 }), 3);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 3 }),
    };

    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(3000);
    expect(inventoryChecker.check).toHaveBeenCalledWith("a", 3);
  });

  it("stops at the first denied line", async () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 1);
    cart.add(product({ id: "b" }), 1);
    const check = vi
      .fn()
      .mockResolvedValueOnce({ available: false })
      .mockResolvedValue({ available: true });
    const inventoryChecker: InventoryChecker = { check };

    await expect(cart.checkout({ inventoryChecker })).rejects.toBeInstanceOf(InventoryError);
    expect(check).toHaveBeenCalledTimes(1);
  });

  it("propagates a rejected inventory checker promise", async () => {
    const cart = new Cart();
    cart.add(product({ id: "a" }), 1);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockRejectedValue(new Error("inventory offline")),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow("inventory offline");
  });

  it("uses the async tax provider composed with discount and shipping", async () => {
    const discountPolicy: DiscountPolicy = { computeDiscountCents: () => 500 };
    const shippingCalculator: ShippingCalculator = { computeShippingCents: () => 300 };
    const cart = new Cart({ discountPolicy, shippingCalculator, region: "US-CA" });
    cart.add(product({ unitPriceCents: 1000 }), 2); // subtotal 2000, discounted 1500

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };

    const result = await cart.checkout({ asyncTaxProvider });

    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.totals.discountCents).toBe(500);
    // 0.1 * 1500 = 150
    expect(result.totals.taxCents).toBe(150);
    expect(result.totals.shippingCents).toBe(300);
    expect(result.totals.totalCents).toBe(1500 + 150 + 300);
  });

  it("propagates a rejected async tax provider promise", async () => {
    const cart = new Cart();
    cart.add(product({ unitPriceCents: 1000 }), 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service down");
  });

  it("returns synchronous totals when no async tax provider is supplied", async () => {
    const cart = new Cart();
    cart.add(product({ unitPriceCents: 1000 }), 2);
    const result = await cart.checkout();
    expect(result.totals.totalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
  });
});
