public class RegistrationService
{
    // Simulates emails already registered for this event.
    private static readonly HashSet<string> AlreadyRegisteredEmails = new(StringComparer.OrdinalIgnoreCase)
    {
        "taken@example.com"
    };

    /// <summary>
    /// Performs server-side validation of a registration. Returns a dictionary
    /// keyed by model field name, where each value is the list of error messages
    /// for that field. An empty dictionary means the registration is valid.
    /// </summary>
    public async Task<Dictionary<string, List<string>>> ValidateAsync(RegistrationModel model)
    {
        // Simulate a server round-trip (database/API lookup).
        await Task.Delay(400);

        var errors = new Dictionary<string, List<string>>();

        if (!string.IsNullOrWhiteSpace(model.Email) &&
            AlreadyRegisteredEmails.Contains(model.Email.Trim()))
        {
            errors[nameof(RegistrationModel.Email)] = new List<string>
            {
                "This email is already registered"
            };
        }

        return errors;
    }
}
