{"path":"C:\Users\aajohn\AppData\Local\Temp\sv-5a86f728de50419e8512b7ba8a38e4ac\Components\CustomValidator.cs","file_text":"using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Forms;

namespace sv_5a86f728de50419e8512b7ba8a38e4ac.Components;

/// <summary>
/// Bridges server-side validation results into an <see cref="EditContext"/> so
/// that field-specific errors render next to the matching input via
/// &lt;ValidationMessage&gt;.
/// </summary>
public class CustomValidator : ComponentBase
{
    [CascadingParameter]
    private EditContext? EditContext { get; set; }

    private ValidationMessageStore? messageStore;

    protected override void OnInitialized()
    {
        if (EditContext is null)
        {
            throw new InvalidOperationException(
                $"{nameof(CustomValidator)} must be placed inside an EditForm.");
        }

        messageStore = new ValidationMessageStore(EditContext);

        // Clear server errors whenever the form is re-validated or a field changes,
        // so the user can edit the email and try again.
        EditContext.OnValidationRequested += (_, _) => messageStore.Clear();
        EditContext.OnFieldChanged += (_, e) => messageStore.Clear(e.FieldIdentifier);
    }

    public void DisplayErrors(Dictionary<string, List<string>> errors)
    {
        foreach (var (field, messages) in errors)
        {
            messageStore!.Add(EditContext!.Field(field), messages);
        }

        EditContext!.NotifyValidationStateChanged();
    }

    public void ClearErrors()
    {
        messageStore?.Clear();
        EditContext?.NotifyValidationStateChanged();
    }
}
"}

