public interface IAppointmentService
{
    Task<IReadOnlyList<string>> GetDoctorsAsync();

    Task<IReadOnlyList<string>> GetAvailableSlotsAsync(string? doctor, DateOnly? date);

    Task<PatientValidationResult> ValidatePatientAsync(AppointmentModel model);

    Task<string> BookAsync(AppointmentModel model);
}

/// <summary>
/// Stubbed appointment service that simulates server-side lookups and validation
/// rules. It is intentionally in-memory and deterministic so the booking flow can
/// be exercised end to end.
/// </summary>
public class AppointmentService : IAppointmentService
{
    private static readonly string[] AllDoctors = { "Dr. Smith", "Dr. Jones", "Dr. Patel" };

    // Doctors that do NOT accept self-pay (i.e. patients with "None" insurance).
    private static readonly HashSet<string> SelfPayRejectingDoctors = new(StringComparer.OrdinalIgnoreCase)
    {
        "Dr. Smith",
    };

    private const string OutstandingBalanceEmail = "taken@example.com";
    private const string TakenSlot = "10:00 AM";

    public async Task<IReadOnlyList<string>> GetDoctorsAsync()
    {
        await Task.Delay(150);
        return AllDoctors;
    }

    public async Task<IReadOnlyList<string>> GetAvailableSlotsAsync(string? doctor, DateOnly? date)
    {
        await Task.Delay(150);

        if (string.IsNullOrEmpty(doctor) || date is null)
        {
            return Array.Empty<string>();
        }

        // "10:00 AM" is always offered so the "slot no longer available" race can be demonstrated.
        return new[] { "9:00 AM", "10:00 AM", "11:00 AM", "1:00 PM", "2:30 PM" };
    }

    public async Task<PatientValidationResult> ValidatePatientAsync(AppointmentModel model)
    {
        await Task.Delay(250);

        var result = new PatientValidationResult();

        if (string.Equals(model.Email, OutstandingBalanceEmail, StringComparison.OrdinalIgnoreCase))
        {
            result.AddError(nameof(AppointmentModel.Email), "Account has outstanding balance");
        }

        if (string.Equals(model.Insurance, "None", StringComparison.OrdinalIgnoreCase)
            && !string.IsNullOrEmpty(model.Doctor)
            && SelfPayRejectingDoctors.Contains(model.Doctor))
        {
            result.AddError(nameof(AppointmentModel.Doctor), "Selected doctor does not accept self-pay patients");
        }

        if (string.Equals(model.TimeSlot, TakenSlot, StringComparison.OrdinalIgnoreCase))
        {
            result.AddError(nameof(AppointmentModel.TimeSlot), "This slot is no longer available");
        }

        return result;
    }

    public async Task<string> BookAsync(AppointmentModel model)
    {
        await Task.Delay(250);
        var confirmation = $"APPT-{Guid.NewGuid().ToString("N")[..8].ToUpperInvariant()}";
        return confirmation;
    }
}
"}

