@code {
    private static readonly string[] InsuranceProviders =
        { "Aetna", "BlueCross", "Cigna", "UnitedHealth", "None" };

    private static readonly string[] Step1Fields =
    {
        nameof(AppointmentModel.Name),
        nameof(AppointmentModel.Email),
        nameof(AppointmentModel.Phone),
        nameof(AppointmentModel.Insurance),
    };

    private static readonly string[] Step2Fields =
    {
        nameof(AppointmentModel.Doctor),
        nameof(AppointmentModel.Date),
        nameof(AppointmentModel.TimeSlot),
        nameof(AppointmentModel.Reason),
    };

    private readonly AppointmentModel model = new();

    private EditContext editContext = default!;
    private ValidationMessageStore annotationMessages = default!;
    private ValidationMessageStore serverMessages = default!;

    private List<string> doctors = new();
    private List<string> timeSlots = new();
    private int slotLoadToken;

    private bool step2Visible;
    private bool isBusy;
    private bool booked;
    private string? confirmationNumber;

    protected override void OnInitialized()
    {
        editContext = new EditContext(model);
        annotationMessages = new ValidationMessageStore(editContext);
        serverMessages = new ValidationMessageStore(editContext);

        editContext.OnValidationRequested += HandleValidationRequested;
        editContext.OnFieldChanged += HandleFieldChanged;
    }

    // Validate only the fields for the steps that are currently visible so that
    // hidden step-2 fields do not generate errors while the user is still on step 1.
    private void HandleValidationRequested(object? sender, ValidationRequestedEventArgs e)
    {
        annotationMessages.Clear();

        ValidateFields(Step1Fields);
        if (step2Visible)
        {
            ValidateFields(Step2Fields);
        }

        editContext.NotifyValidationStateChanged();
    }

    private void ValidateFields(IEnumerable<string> fieldNames)
    {
        foreach (var name in fieldNames)
        {
            var property = typeof(AppointmentModel).GetProperty(name)!;
            var value = property.GetValue(model);
            var context = new ValidationContext(model) { MemberName = name };
            var results = new List<ValidationResult>();

            if (!Validator.TryValidateProperty(value, context, results))
            {
                foreach (var result in results)
                {
                    annotationMessages.Add(editContext.Field(name), result.ErrorMessage ?? "Invalid value.");
                }
            }
        }
    }

    // Server errors are attached to one field but may be resolved by editing a
    // related field, so clear them by dependency rather than by the edited field alone.
    private void HandleFieldChanged(object? sender, FieldChangedEventArgs e)
    {
        switch (e.FieldIdentifier.FieldName)
        {
            case nameof(AppointmentModel.Email):
                serverMessages.Clear(editContext.Field(nameof(AppointmentModel.Email)));
                break;

            case nameof(AppointmentModel.Insurance):
                serverMessages.Clear(editContext.Field(nameof(AppointmentModel.Doctor)));
                break;

            case nameof(AppointmentModel.Doctor):
                serverMessages.Clear(editContext.Field(nameof(AppointmentModel.Doctor)));
                serverMessages.Clear(editContext.Field(nameof(AppointmentModel.TimeSlot)));
                break;

            case nameof(AppointmentModel.Date):
            case nameof(AppointmentModel.TimeSlot):
                serverMessages.Clear(editContext.Field(nameof(AppointmentModel.TimeSlot)));
                break;
        }

        editContext.NotifyValidationStateChanged();
    }

    private async Task HandlePrimaryAsync()
    {
        if (isBusy)
        {
            return;
        }

        if (!step2Visible)
        {
            await CheckAvailabilityAsync();
        }
        else
        {
            await BookAsync();
        }
    }

    private async Task CheckAvailabilityAsync()
    {
        serverMessages.Clear();

        if (!editContext.Validate())
        {
            return;
        }

        isBusy = true;
        try
        {
            // Between steps only patient-level rules (e.g. account balance) can be
            // evaluated; doctor/time-slot rules are re-checked before booking.
            var result = await Appointments.ValidatePatientAsync(model);
            if (ApplyServerErrors(result))
            {
                return;
            }

            doctors = (await Appointments.GetDoctorsAsync()).ToList();
            step2Visible = true;
        }
        finally
        {
            isBusy = false;
        }
    }

    private async Task BookAsync()
    {
        serverMessages.Clear();

        if (!editContext.Validate())
        {
            return;
        }

        isBusy = true;
        try
        {
            var result = await Appointments.ValidatePatientAsync(model);
            if (ApplyServerErrors(result))
            {
                return;
            }

            confirmationNumber = await Appointments.BookAsync(model);
            booked = true;
        }
        finally
        {
            isBusy = false;
        }
    }

    private bool ApplyServerErrors(PatientValidationResult result)
    {
        if (!result.HasErrors)
        {
            return false;
        }

        foreach (var (field, messages) in result.FieldErrors)
        {
            foreach (var message in messages)
            {
                serverMessages.Add(editContext.Field(field), message);
            }
        }

        editContext.NotifyValidationStateChanged();
        return true;
    }

    private async Task OnDoctorOrDateChanged()
    {
        // The available slots depend on the doctor and date, so a previously chosen
        // slot is no longer valid once either changes.
        model.TimeSlot = null;
        await ReloadSlotsAsync();
    }

    private async Task ReloadSlotsAsync()
    {
        var token = ++slotLoadToken;
        timeSlots = new();

        var slots = await Appointments.GetAvailableSlotsAsync(model.Doctor, model.Date);

        // Ignore stale responses if another reload started in the meantime.
        if (token == slotLoadToken)
        {
            timeSlots = slots.ToList();
        }
    }

    private void StartOver()
    {
        foreach (var property in typeof(AppointmentModel).GetProperties())
        {
            property.SetValue(model, null);
        }

        annotationMessages.Clear();
        serverMessages.Clear();
        doctors = new();
        timeSlots = new();
        step2Visible = false;
        booked = false;
        confirmationNumber = null;
        editContext.NotifyValidationStateChanged();
    }
}
