var builder = WebApplication.CreateBuilder(args);

builder.Services.AddOpenTelemetry()
    .ConfigureResource(resource => resource
        .AddService(serviceName: builder.Environment.ApplicationName))
    .WithTracing(tracing => tracing
        .AddAspNetCoreInstrumentation(options =>
        {
            options.Filter = httpContext =>
                !httpContext.Request.Path.StartsWithSegments("/healthz");
        })
        .AddHttpClientInstrumentation(options => options.RecordException = true)
        // Must match the ActivitySource name in OrderService
        .AddSource("MyApp.Orders"))
    .WithMetrics(metrics => metrics
        .AddAspNetCoreInstrumentation()
        .AddHttpClientInstrumentation()
        // Must match the Meter name in OrderService
        .AddMeter("MyApp.Orders"))
    // Single OTLP exporter for all signals. Reads OTEL_EXPORTER_OTLP_ENDPOINT
    // (defaults to http://localhost:4317 over gRPC).
    .UseOtlpExporter();

builder.Services.AddScoped<OrderService>();

var app = builder.Build();

app.MapControllers();
app.Run();
```

## OrderService.cs

