using System.Diagnostics;
using System.Diagnostics.Metrics;

public class OrderService
{
    // Static ActivitySource — name MUST match AddSource("MyApp.Orders")
    private static readonly ActivitySource ActivitySource = new("MyApp.Orders");

    private readonly Counter<long> _ordersProcessed;
    private readonly ILogger<OrderService> _logger;

    public OrderService(IMeterFactory meterFactory, ILogger<OrderService> logger)
    {
        _logger = logger;

        // Meter name MUST match AddMeter("MyApp.Orders")
        var meter = meterFactory.Create("MyApp.Orders");
        _ordersProcessed = meter.CreateCounter<long>(
            "orders.processed", unit: "orders",
            description: "Total orders successfully processed");
    }

    public async Task<Order> ProcessOrder(CreateOrderRequest request)
    {
        // Custom span around the whole operation
        using var activity = ActivitySource.StartActivity("ProcessOrder");
        activity?.SetTag("order.customer_id", request.CustomerId);
        activity?.SetTag("order.item_count", request.Items.Count);

        try
        {
            await ValidateAsync(request);
            await ChargePaymentAsync(request);

            var order = new Order
            {
                Id = Guid.NewGuid(),
                CustomerId = request.CustomerId,
                Status = "Completed"
            };

            activity?.SetStatus(ActivityStatusCode.Ok);

            // Increment the counter. Keep tags low-cardinality (no IDs/UUIDs).
            _ordersProcessed.Add(1, new TagList
            {
                { "order.type", "standard" }
            });

            return order;
        }
        catch (Exception ex)
        {
            activity?.SetStatus(ActivityStatusCode.Error, ex.Message);
            _logger.LogError(ex, "Order processing failed for {CustomerId}", request.CustomerId);
            throw;
        }
    }

    private Task ValidateAsync(CreateOrderRequest request) => Task.CompletedTask;
    private Task ChargePaymentAsync(CreateOrderRequest request) => Task.CompletedTask;
}
```

## Key points

- **Names must match exactly.** `ActivitySource("MyApp.Orders")` ↔ `AddSource("MyApp.Orders")`, and `meter.Create("MyApp.Orders")` ↔ `AddMeter("MyApp.Orders")`. Mismatches are silently ignored — the #1 cause of "nothing shows up."
- **Counter via `IMeterFactory`**, not `new Meter()`, for proper DI lifetime.
- **`ActivitySource` is static**; `StartActivity` returns null if no listener is registered, so the `activity?.` null-conditional calls are intentional.
- **OTLP endpoint**: gRPC on port `4317` by default. Set `OTEL_EXPORTER_OTLP_ENDPOINT` to point at your collector. If it only accepts HTTP, use port `4318` and configure `OtlpExportProtocol.HttpProtobuf`.

