/// <summary>
/// Tracks the number of items below their minimum stock level for the current warehouse.
///
/// Registered as a <b>scoped</b> service so that every warehouse manager (each Blazor circuit)
/// gets an independent instance: one manager switching sites or polling never affects another.
///
/// The <see cref="OnChange"/> event lets components that are NOT in a parent-child relationship
/// (the sidebar badge, the dashboard badge, etc.) react whenever fresh data arrives. Because the
/// polling timer fires on a background thread, subscribers must marshal their re-render back onto
/// the Blazor synchronization context with <c>InvokeAsync(StateHasChanged)</c>.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private static readonly TimeSpan PollInterval = TimeSpan.FromSeconds(10);

    private readonly Random _random = new();
    private Timer? _timer;
    private string? _warehouseId;
    private int _pollGate;

    /// <summary>The most recent low-stock count for the current warehouse.</summary>
    public int LowStockCount { get; private set; }

    /// <summary>Whether the 10-second polling loop is currently active.</summary>
    public bool IsPolling => _timer is not null;

    /// <summary>Raised whenever <see cref="LowStockCount"/> changes so all subscribers can refresh.</summary>
    public event Action? OnChange;

    /// <summary>
    /// Simulates a database query for the number of items below minimum stock level.
    /// Returns a random number between 0 and 15 (inclusive).
    /// </summary>
    public async Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate database/network latency.
        await Task.Delay(150);
        return _random.Next(0, 16);
    }

