/// <summary>
/// Tracks the number of items below their minimum stock level for the current warehouse.
///
/// Registered as a <b>scoped</b> service so that every warehouse manager (each Blazor circuit)
/// gets an independent instance: one manager switching sites or polling never affects another.
///
/// The <see cref="OnChange"/> event lets components that are NOT in a parent-child relationship
/// (the sidebar badge, the dashboard badge, etc.) react whenever fresh data arrives. Because the
/// polling timer fires on a background thread, subscribers must marshal their re-render back onto
/// the Blazor synchronization context with <c>InvokeAsync(StateHasChanged)</c>.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private static readonly TimeSpan PollInterval = TimeSpan.FromSeconds(10);

    private readonly Random _random = new();
    private Timer? _timer;
    private string? _warehouseId;

    // Bumped whenever the target warehouse changes (or polling stops). A poll that completes with
    // a stale generation is discarded so a late result never overwrites the current warehouse's count.
    private int _generation;

    // Serializes polls (0 = idle, 1 = a drain loop is running) and records that another refresh
    // was requested while one was in flight, guaranteeing an immediate refresh after a site switch.
    private int _pollGate;
    private int _refreshRequested;

    /// <summary>The most recent low-stock count for the current warehouse.</summary>
    public int LowStockCount { get; private set; }

    /// <summary>Whether the 10-second polling loop is currently active.</summary>
    public bool IsPolling => _timer is not null;

    /// <summary>Raised whenever <see cref="LowStockCount"/> changes so all subscribers can refresh.</summary>
    public event Action? OnChange;

    /// <summary>
    /// Simulates a database query for the number of items below minimum stock level.
    /// Returns a random number between 0 and 15 (inclusive).
    /// </summary>
    public async Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate database/network latency.
        await Task.Delay(150);
        return _random.Next(0, 16);
    }

    /// <summary>
    /// Starts the 10-second polling loop for the given warehouse, refreshing immediately.
    /// If already polling, retargets to the new warehouse and refreshes right away so a site
    /// switch is reflected without waiting for the next tick.
    /// </summary>
    public void StartPolling(string warehouseId)
    {
        _warehouseId = warehouseId;
        Interlocked.Increment(ref _generation);

        _timer ??= new Timer(TimerTick, null, TimeSpan.Zero, PollInterval);

        // Timer's due-time fires the first poll for a brand-new timer; for an already-running
        // timer (e.g. a warehouse switch) request an out-of-band refresh now.
        RequestRefresh();
    }

    /// <summary>Stops the polling loop. Called when the manager leaves the dashboard.</summary>
    public void StopPolling()
    {
        _timer?.Dispose();
        _timer = null;

        // Invalidate any in-flight poll so a late result can't update a badge after we've stopped.
        Interlocked.Increment(ref _generation);
    }

    private void TimerTick(object? state) => RequestRefresh();

    private void RequestRefresh()
    {
        Interlocked.Exchange(ref _refreshRequested, 1);

        // Only one drain loop runs at a time; if one is already active it will pick up the request.
        if (Interlocked.CompareExchange(ref _pollGate, 1, 0) == 0)
        {
            _ = DrainAsync();
        }
    }

    private async Task DrainAsync()
    {
        try
        {
            while (Interlocked.Exchange(ref _refreshRequested, 0) == 1)
            {
                var warehouseId = _warehouseId;
                if (warehouseId is null)
                {
                    continue;
                }

                var generation = Volatile.Read(ref _generation);

                int count;
                try
                {
                    count = await GetLowStockCountAsync(warehouseId);
                }
                catch
                {
                    // A failed simulated query is skipped; a later tick/request retries.
                    continue;
                }

                // Discard results superseded by a warehouse switch or a stop while we awaited.
                if (Volatile.Read(ref _generation) != generation)
                {
                    continue;
                }

                LowStockCount = count;
                OnChange?.Invoke();
            }
        }
        finally
        {
            Interlocked.Exchange(ref _pollGate, 0);
        }

        // A request that arrived in the gap between the loop exit and releasing the gate would
        // otherwise be lost, so re-check and restart the loop if needed.
        if (Volatile.Read(ref _refreshRequested) == 1 &&
            Interlocked.CompareExchange(ref _pollGate, 1, 0) == 0)
        {
            _ = DrainAsync();
        }
    }

    public void Dispose() => _timer?.Dispose();
}
