public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Per-circuit theme state shared across every page and component.
/// Registered as scoped so each user's circuit gets its own instance,
/// and it crosses render-mode boundaries (unlike a &lt;CascadingValue&gt; in a static layout).
/// </summary>
public class ThemeState
{
    private ThemeMode _mode = ThemeMode.System;
    private string _accent = "#512bd4";

    /// <summary>Raised whenever <see cref="Mode"/> or <see cref="Accent"/> actually changes.</summary>
    public event Action? OnChange;

    public ThemeMode Mode => _mode;

    public string Accent => _accent;

    public void SetMode(ThemeMode mode)
    {
        if (_mode == mode)
        {
            return;
        }

        _mode = mode;
        OnChange?.Invoke();
    }

    public void SetAccent(string accent)
    {
        if (string.Equals(_accent, accent, StringComparison.Ordinal))
        {
            return;
        }

        _accent = accent;
        OnChange?.Invoke();
    }

    public void Set(ThemeMode mode, string accent)
    {
        var changed = _mode != mode || !string.Equals(_accent, accent, StringComparison.Ordinal);
        if (!changed)
        {
            return;
        }

        _mode = mode;
        _accent = accent;
        OnChange?.Invoke();
    }
}
"}

