1. namespace ContosoUniversity.Services;
2. 
3. public class StudentService
4. {
5.     private readonly List<Student> _students = new();
6. 
7.     /// <summary>
8.     /// Enroll a student. Validates name, age, and duplicate checks.
9.     /// Complexity: moderate (multiple branches).
10.     /// </summary>
11.     public EnrollmentResult Enroll(string firstName, string lastName, int age)
12.     {
13.         if (string.IsNullOrWhiteSpace(firstName) || string.IsNullOrWhiteSpace(lastName))
14.             return new EnrollmentResult(false, "Name is required.");
15. 
16.         if (age < 16 || age > 100)
17.             return new EnrollmentResult(false, "Age must be between 16 and 100.");
18. 
19.         var existing = _students.FirstOrDefault(s =>
20.             s.FirstName.Equals(firstName, StringComparison.OrdinalIgnoreCase) &&
21.             s.LastName.Equals(lastName, StringComparison.OrdinalIgnoreCase));
22. 
23.         if (existing != null)
24.             return new EnrollmentResult(false, $"Student {firstName} {lastName} is already enrolled.");
25. 
26.         var student = new Student
27.         {
28.             Id = _students.Count + 1,
29.             FirstName = firstName,
30.             LastName = lastName,
31.             Age = age,
32.             EnrolledDate = DateTime.UtcNow
33.         };
34. 
35.         _students.Add(student);
36.         return new EnrollmentResult(true, "Enrolled successfully.", student.Id);
37.     }
38. 
39.     /// <summary>
40.     /// Calculate GPA from a list of grades. Handles edge cases.
41.     /// Complexity: high (loops, conditionals, null checks).
42.     /// </summary>
43.     public GpaResult CalculateGpa(int studentId, List<Grade>? grades)
44.     {
45.         var student = _students.FirstOrDefault(s => s.Id == studentId);
46.         if (student == null)
47.             return new GpaResult(false, 0, "Student not found.");
48. 
49.         if (grades == null || grades.Count == 0)
50.             return new GpaResult(true, 0, "No grades to calculate.");
51. 
52.         double totalPoints = 0;
53.         int totalCredits = 0;
54.         var warnings = new List<string>();
55. 
56.         foreach (var grade in grades)
57.         {
58.             if (grade.Credits <= 0)
59.             {
60.                 warnings.Add($"Skipped invalid credit value for {grade.CourseName}.");
61.                 continue;
62.             }
63. 
64.             double points = grade.LetterGrade?.ToUpperInvariant() switch
65.             {
66.                 "A" => 4.0,
67.                 "B" => 3.0,
68.                 "C" => 2.0,
69.                 "D" => 1.0,
70.                 "F" => 0.0,
71.                 _ => -1.0
72.             };
73. 
74.             if (points < 0)
75.             {
76.                 warnings.Add($"Unknown grade '{grade.LetterGrade}' for {grade.CourseName}.");
77.                 continue;
78.             }
79. 
80.             totalPoints += points * grade.Credits;
81.             totalCredits += grade.Credits;
82.         }
83. 
84.         if (totalCredits == 0)
85.             return new GpaResult(true, 0, "No valid grades after filtering.");
86. 
87.         double gpa = Math.Round(totalPoints / totalCredits, 2);
88. 
89.         string message = warnings.Count > 0
90.             ? $"GPA calculated with {warnings.Count} warning(s): {string.Join("; ", warnings)}"
91.             : "GPA calculated successfully.";
92. 
93.         return new GpaResult(true, gpa, message);
94.     }
95. 
96.     /// <summary>
97.     /// Simple lookup by ID. Complexity: low (1 branch).
98.     /// </summary>
99.     public Student? FindById(int id)
100.     {
101.         return _students.FirstOrDefault(s => s.Id == id);
102.     }
103. 
104.     /// <summary>
105.     /// Search students by name. Complexity: low.
106.     /// </summary>
107.     public List<Student> Search(string query)
108.     {
109.         if (string.IsNullOrWhiteSpace(query))
110.             return new List<Student>();
111. 
112.         return _students
113.             .Where(s => s.FirstName.Contains(query, StringComparison.OrdinalIgnoreCase) ||
114.                         s.LastName.Contains(query, StringComparison.OrdinalIgnoreCase))
115.             .ToList();
116.     }
117. }
