7. 
8.     public OrderService(IOrderRepository repository, IPaymentGateway paymentGateway)
9.     {
10.         _repository = repository;
11.         _paymentGateway = paymentGateway;
12.     }
13. 
14.     // Complexity: 10 (if, if, ||, for, if, ||, ??, if, if)
15.     public OrderResult ProcessOrder(Order order)
16.     {
17.         if (order == null)
18.             throw new ArgumentNullException(nameof(order));
19. 
20.         if (order.Items == null || order.Items.Count == 0)
21.             return new OrderResult { Success = false, Error = "No items in order" };
22. 
23.         decimal total = 0;
24.         for (int i = 0; i < order.Items.Count; i++)
25.         {
26.             var item = order.Items[i];
27.             if (item.Quantity <= 0 || item.Price < 0)
28.                 return new OrderResult { Success = false, Error = $"Invalid item at index {i}" };
29. 
30.             var discount = item.Discount ?? 0m;
31.             total += (item.Price - discount) * item.Quantity;
32.         }
33. 
34.         if (total <= 0)
35.             return new OrderResult { Success = false, Error = "Order total must be positive" };
36. 
37.         var payment = _paymentGateway.Charge(order.CustomerId, total);
38.         if (!payment.Succeeded)
39.             return new OrderResult { Success = false, Error = payment.ErrorMessage };
40. 
41.         order.Total = total;
42.         order.Status = OrderStatus.Confirmed;
43.         _repository.Save(order);
44. 
45.         return new OrderResult { Success = true, OrderId = order.Id, Total = total };
46.     }
47. 
48.     // Complexity: 6 (if, ||, foreach, if, &&)
49.     public decimal CalculateTotal(List<OrderItem> items)
50.     {
51.         if (items == null || items.Count == 0)
52.             return 0;
53. 
54.         decimal total = 0;
55.         foreach (var item in items)
56.         {
57.             if (item.Quantity > 0 && item.Price >= 0)
58.                 total += item.Price * item.Quantity;
59.         }
60.         return total;
61.     }
62. 
63.     // Complexity: 7 (if, 4 switch arms [_ default excluded], ?:)
64.     public string GetOrderStatus(int orderId)
65.     {
66.         var order = _repository.GetById(orderId);
67.         if (order == null)
68.             return "Not Found";
69. 
70.         return order.Status switch
71.         {
72.             OrderStatus.Pending => "Pending",
73.             OrderStatus.Confirmed => "Confirmed",
74.             OrderStatus.Shipped => order.TrackingNumber != null ? "Shipped (Tracked)" : "Shipped",
75.             OrderStatus.Cancelled => "Cancelled",
76.             _ => "Unknown"
77.         };
78.     }
79. 
80.     // Complexity: 3 (if, &&)
81.     public void CancelOrder(int orderId)
82.     {
83.         var order = _repository.GetById(orderId);
84.         if (order != null && order.Status != OrderStatus.Shipped)
85.         {
86.             order.Status = OrderStatus.Cancelled;
87.             _repository.Save(order);
88.         }
89.     }
90. }
